      const matches = searchCatalog(view.catalog, query, limit, resolved.stem)
      const returned = matches.filter((match) => match.found).map((match) => match.name)
      // 先 `discover`（B8：发现即播种 lastUsed）再淘汰——顺序反了会把刚发现的一批当最旧踢掉。
