      discovery.claim(exec.agent, returned)
      // **只在本次真的新增了名字时淘汰**（B10）：一次"什么都没搜到"的搜索不该踢掉一半。
      if (discoveredNow.length > 0) discovery.evict(exec.agent, discoveredNow.length)
